    91	                    <View style={styles.mb4}>
    92	                        <InputWrapper
    93	                            InputComponent={TextInput}
    94	                            inputID={INPUT_IDS.FIRST_NAME}
    95	                            name="fname"
    96	                            label={translate('common.firstName')}
    97	                            aria-label={translate('common.firstName')}
    98	                            role={CONST.ROLE.PRESENTATION}
    99	                            defaultValue={currentUserDetails.firstName ?? ''}
   100	                            spellCheck={false}
